addQ(T,"What does nvidia-smi help diagnose?","GPU visibility, utilization, and reported errors","Kubernetes namespace RBAC only","Slurm accounting database only","BCM image versions only","nvidia-smi reports GPU state.");
addQ(T,"What is an NVIDIA Xid message?","A GPU driver-reported error event","A Slurm partition","A BCM category","A Kubernetes namespace","Xid events need contextual diagnosis.");
addQ(T,"Why drain a node with an unresolved GPU fault?","Prevent new workloads while investigating","Increase GPU memory","Commit BCM changes","Force container pull","Isolation reduces exposure to a suspected fault.");
addQ(T,"What should you inspect when a GPU pod is Pending?","Pod events and node allocatable GPU resources","Only the pod name","Only the datacenter address","Only the keyboard layout","Scheduling failures often reveal capacity or constraints.");
addQ(T,"What does df -h reveal?","Filesystem capacity and usage","GPU temperature","Kubernetes image tags","Slurm priority","df reports filesystem utilization.");
